use ingetrazo_core::{scene::SelectionItem,intersect::{IntersectMode,segments_for}};
fn main(){let dir=std::path::PathBuf::from(std::env::args().nth(1).unwrap());for name in ["cross","hole","coplanar","groups"]{let mut scene=ingetrazo_formats::igz::load_igz(&dir.join(format!("{name}-source.igz"))).unwrap();let mode=if name=="groups"{scene.select(SelectionItem::Group(0));IntersectMode::WithModel}else{scene.select(SelectionItem::Face(0));IntersectMode::WithContext};let segments=segments_for(&scene,mode).unwrap();let points=segments.iter().map(|(a,b)|[a.to_array(),b.to_array()]).collect::<Vec<_>>();std::fs::write(dir.join(format!("{name}-segments.json")),serde_json::to_vec(&points).unwrap()).unwrap();}let mut scene=ingetrazo_formats::igz::load_igz(&dir.join("bar-source.igz")).unwrap();for i in 0..scene.mesh.faces.len(){scene.select(SelectionItem::Face(i));}ingetrazo_core::intersect::intersect_faces(&mut scene,IntersectMode::WithModel).unwrap();ingetrazo_formats::igz::save_igz(&scene,&dir.join("bar-result.igz")).unwrap();}
